def merge_text(current: str, original: str, desired: str, path: str) -> str:
    with tempfile.TemporaryDirectory(prefix='youtv-merge-') as workspace:
        files = [Path(workspace)/name for name in ('current','original','desired')]
        for file, content in zip(files, (current,original,desired)):
            file.write_text(content,encoding='utf-8')
        result=subprocess.run(['git','merge-file','-p',*map(str,files)],
            stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        if result.returncode!=0:
            raise RuntimeError(f'{path}: merge conflict (git merge-file exit {result.returncode}): {result.stderr.strip()}')
        return result.stdout

def main() -> int:
    parser=argparse.ArgumentParser(description='YouTV 0.34 safe upgrade')
    group=parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--check',action='store_true',help='verify without modifying files')
    group.add_argument('--apply',action='store_true',help='backup and apply an all-or-nothing upgrade')
    args=parser.parse_args()
    root=Path(__file__).resolve().parent.parent
    if not (root/'apps/worker/src/index.ts').is_file():
        raise RuntimeError('Run this from a YouTV repository: apps/worker/src/index.ts was not found')
    payload=json.loads(zlib.decompress(base64.b85decode(PAYLOAD)).decode('utf-8'))
    changes={}
    for name, contents in payload.items():
        location=root/name
        original=contents['base']
        desired=contents['target']
        if location.exists() and not location.is_file():
            raise RuntimeError(f'{name}: a directory exists where a file is needed')
        current=location.read_text('utf-8') if location.exists() else None
        if current==desired:continue
        if current==original:
            changes[name]=(current,desired)
        elif current is None or original is None:
            raise RuntimeError(f'{name}: unexpected existing/missing file; refusing to overwrite')
        else:
            changes[name]=(current,merge_text(current,original,desired,name))
    print(f'YouTV v{RELEASE}: {len(changes)} file(s) need upgrading.')
    for name in changes:print('  '+name)
    if args.check:
        print('CHECK OK: no files changed.')
        return 0
    if not changes:
        print('Already upgraded; run bun install && bun run build && bun run test.')
        return 0
    gitdir=subprocess.run(['git','rev-parse','--git-dir'],cwd=root,capture_output=True,text=True)
    if gitdir.returncode:
        raise RuntimeError('A Git working tree is required for safe backups')
    gitpath=Path(gitdir.stdout.strip());gitpath=gitpath if gitpath.is_absolute() else root/gitpath
    timestamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
    backup=gitpath/'youtv-upgrade-backups'/f'v034-{timestamp}'
    # Prepare the entire backup before modifying even the first file.
    for name,(previous,_) in changes.items():
        if previous is None:continue
        destination=backup/name
        destination.parent.mkdir(parents=True,exist_ok=True)
        destination.write_text(previous,encoding='utf-8')
    for name,(_,new) in changes.items():
        destination=root/name
        destination.parent.mkdir(parents=True,exist_ok=True)
        # Atomic file replacement avoids truncated source files.
        with tempfile.NamedTemporaryFile(mode='w',encoding='utf-8',
           dir=destination.parent,prefix='.youtv-upgrade-',delete=False) as f:
            f.write(new);temp=Path(f.name)
        temp.replace(destination)
    print(f'Upgrade applied. Previous files backed up under {backup}')
    print('Next: bun install && bun run build && bun run test')
    return 0

if __name__=='__main__':
    try:sys.exit(main())
    except Exception as error:
        print('UPGRADE STOPPED: '+str(error),file=sys.stderr)
        sys.exit(1)
